-- Paket 13.11.2026 (3): cart quick-add block (new chunk HtsCartQuickAdd, resource 12). Text is hex-encoded on purpose.
SET NAMES utf8mb4;
SET SESSION group_concat_max_len = 100000;
-- APPLY. Saves the page content to hts_bak_20261113_qa first; safe to run twice.
CREATE TABLE IF NOT EXISTS hts_bak_20261113_qa (kind VARCHAR(16) NOT NULL, el_id INT NOT NULL, body MEDIUMTEXT, saved_at DATETIME NOT NULL, PRIMARY KEY (kind, el_id)) DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO hts_bak_20261113_qa (kind, el_id, body, saved_at) SELECT 'resource', r.id, r.content, NOW() FROM modx_site_content r WHERE r.id = 12 AND r.content NOT LIKE '%[[$HtsCartQuickAdd]]%';
UPDATE modx_site_content r SET r.content = REPLACE(CONVERT(r.content USING utf8mb4), _utf8mb4 0x3C64697620636C6173733D226D73325F746F74616C5F70726F6475637473223E, _utf8mb4 0x5B5B2448747343617274517569636B4164645D5D0A3C64697620636C6173733D226D73325F746F74616C5F70726F6475637473223E)
WHERE r.id = 12 AND r.alias = 'cart' AND r.content NOT LIKE '%[[$HtsCartQuickAdd]]%' AND ROUND((CHAR_LENGTH(CONVERT(r.content USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(r.content USING utf8mb4), _utf8mb4 0x3C64697620636C6173733D226D73325F746F74616C5F70726F6475637473223E, ''))) / 32) = 1;
INSERT INTO modx_site_htmlsnippets (source, name, description, category, snippet, properties, static, static_file)
SELECT 1, 'HtsCartQuickAdd', _utf8mb4 0xD091D0BBD0BED0BA20C2ABD094D0BED0B1D0B0D0B2D0B8D182D18C20D182D0BED0B2D0B0D18020D0BFD0BE2DD0B1D18BD181D182D180D0BED0BCD183C2BB20D0B220D0BAD0BED180D0B7D0B8D0BDD0B53A20D0BFD0BED0B4D0BFD0B8D181D0B82C20D0BAD0BED0BBD0B8D187D0B5D181D182D0B2D0BE2C20D181D183D0BCD0BCD0B0, 0, _utf8mb4 , 'a:0:{}', 0, '' FROM (SELECT 1 AS x) d
WHERE NOT EXISTS (SELECT 1 FROM modx_site_htmlsnippets WHERE name = 'HtsCartQuickAdd');
SELECT itog, COUNT(*) AS n, GROUP_CONCAT(chto ORDER BY chto SEPARATOR '; ') AS what FROM (
SELECT _utf8mb4 0x312E20D0A1D182D180D0B0D0BDD0B8D186D0B020C2ABD09AD0BED180D0B7D0B8D0BDD0B0C2BB2028313229 AS chto, CASE WHEN r.id IS NULL THEN _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 WHEN r.content LIKE '%[[$HtsCartQuickAdd]]%' THEN _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E WHEN ROUND((CHAR_LENGTH(CONVERT(r.content USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(r.content USING utf8mb4), _utf8mb4 0x3C64697620636C6173733D226D73325F746F74616C5F70726F6475637473223E, ''))) / 32) = 1 THEN _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C ELSE _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 END AS itog
FROM (SELECT 1 AS x) d LEFT JOIN modx_site_content r ON r.id = 12 AND r.alias = 'cart'
UNION ALL
SELECT _utf8mb4 0x322E20D09DD0BED0B2D18BD0B920D187D0B0D0BDD0BA2048747343617274517569636B416464, CASE WHEN (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'HtsCartQuickAdd') = 0 THEN _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C ELSE _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E END
) q GROUP BY itog;
